```java
@Component
class IdempotencyExecutor {
  private final TransactionTemplate txTemplate;
  StoredResponse execute(String requestId, String fingerprint, Supplier<StoredResponse> action) {
    var existing = repo.find(requestId);
    if (existing.isPresent()) return replayOrConflict(existing.get(), fingerprint);
    try {
      return txTemplate.execute(status -> {
        StoredResponse resp = action.get();
        repo.insert(requestId, fingerprint, resp);
        return resp;
      });
    } catch (DuplicateKeyException e) {
      return repo.find(requestId)
        .map(rec -> replayOrConflict(rec, fingerprint))
        .orElseThrow(() -> new BizException(409, "IN_FLIGHT_CONFLICT", "..."));
    }
  }
}
```

