package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时间源配置：统一使用 UTC 时钟，授权码有效期与生效窗口均按 UTC 口径计算。
 * 测试中可替换为可控时钟以覆盖时间边界。
 */
@Configuration
public class TimeConfig {

    /**
     * 提供系统 UTC 时钟。
     */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.portability.model;

/**
 * 携号转网流程状态。
 * ACTIVATED 与 CANCELLED 为终态；进入终态后在途唯一键 active_key 置空。
 */
public enum FlowStatus {

    /** 已申请（资格校验通过，待签发授权码）。 */
    APPLIED,
    /** 已签发授权码（待携出方确认）。 */
    CODE_ISSUED,
    /** 携出方已确认（待生效窗口广播）。 */
    DONOR_CONFIRMED,
    /** 已生效（终态），授权码立即作废。 */
    ACTIVATED,
    /** 已撤销（终态）。 */
    CANCELLED;

    /**
     * 判断是否为终态。
     */
    public boolean isTerminal() {
        return this == ACTIVATED || this == CANCELLED;
    }
}

package com.example.starter.portability.model;

import java.time.Instant;

/**
 * 携号转网流程记录，对应 portability_flow 表。
 * 时间字段均为 UTC、毫秒精度；authCode* 在未签码时为 null。
 */
public record FlowRecord(
        long id,
        String requestId,
        String msisdn,
        FlowStatus status,
        String authCode,
        Instant authCodeIssuedAt,
        Instant authCodeExpiresAt,
        long version,
        Instant createdAt,
        Instant updatedAt) {
}

package com.example.starter.portability.model;

import java.time.Instant;

/**
 * 流程事件记录，对应 portability_event 表，按 id 升序即发生顺序。
 */
public record EventRecord(
        long id,
        long flowId,
        String eventType,
        String detail,
        Instant createdAt) {
}

