package com.example.starter.portability.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * 携号转网申请请求。
 *
 * @param requestId 幂等请求标识，指纹组成部分
 * @param msisdn    携转手机号码（合成数据）
 */
public record ApplyRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Pattern(regexp = "\\d{6,20}", message = "msisdn 须为 6-20 位数字") String msisdn) {
}

package com.example.starter.portability.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 仅含幂等请求标识的请求体，用于签码、携出方确认、生效广播与撤销。
 *
 * @param requestId 幂等请求标识，指纹组成部分
 */
public record RequestIdRequest(
        @NotBlank @Size(max = 64) String requestId) {
}

package com.example.starter.portability.dto;

import java.time.Instant;

import com.example.starter.portability.model.FlowRecord;
import com.example.starter.portability.model.FlowStatus;

/**
 * 流程状态响应。时间字段为 UTC、毫秒精度；未签码时授权码相关字段为 null。
 */
public record FlowResponse(
        long flowId,
        String msisdn,
        FlowStatus status,
        String authCode,
        Instant authCodeIssuedAt,
        Instant authCodeExpiresAt,
        long version,
        Instant createdAt,
        Instant updatedAt) {

    /**
     * 由流程记录构造响应。
     */
    public static FlowResponse from(FlowRecord flow) {
        return new FlowResponse(
                flow.id(),
                flow.msisdn(),
                flow.status(),
                flow.authCode(),
                flow.authCodeIssuedAt(),
                flow.authCodeExpiresAt(),
                flow.version(),
                flow.createdAt(),
                flow.updatedAt());
    }
}

package com.example.starter.portability.dto;

import java.time.Instant;

import com.example.starter.portability.model.EventRecord;

/**
 * 流程事件响应，按 id 升序返回。
 */
public record EventResponse(
        long id,
        String eventType,
        String detail,
        Instant createdAt) {

    /**
     * 由事件记录构造响应。
     */
    public static EventResponse from(EventRecord event) {
        return new EventResponse(event.id(), event.eventType(), event.detail(), event.createdAt());
    }
}

