@Component
public class IdempotencyExecutor {
    private final PortabilityRepository repository;
    private final TransactionTemplate txTemplate;
    private final Clock clock;

    public StoredResponse execute(String requestId, String endpoint, String fingerprint, Supplier<StoredResponse> action) {
        var existing = repository.findIdempotency(requestId);
        if (existing.isPresent()) {
            return replay(existing.get(), endpoint, fingerprint);
        }
        try {
            return txTemplate.execute(status -> {
                StoredResponse response = action.get();
                Long flowId = extractFlowId? 
                repository.insertIdempotency(requestId, endpoint, fingerprint, response.httpStatus(), response.body(), flowId, Instant.now(clock));
                return response;
            });
        } catch (DuplicateKeyException e) {
            return repository.findIdempotency(requestId)
                    .map(rec -> replay(rec, endpoint, fingerprint))
                    .orElseThrow(() -> new BizException(409, "IN_FLIGHT_CONFLICT", "同一号码已有在途流程，申请被拒绝"));
        }
    }
}
